# Permanent regression test for the signed-zero defect of narrow (2026-11-14).
# History: orl/gen/sweeps-run1-FAILED-signed-zero.txt. An earlier narrow returned +0 where the IEEE double-to-float
# conversion returns -0 (a tiny negative value that rounds to zero). The repair is narrow's first branch,
#   if (fabs(v) <= HH) return v * 0.0;
# This script writes and builds a small C program holding three variants of narrow:
#   narrow_cur   the current narrow, copied from orl/gen/sweep.c (generated by orl/emit.py)
#   narrow_old   the current narrow without its first branch (the variant this test is required to catch)
#   narrow_run1  the narrow of the failed run, copied from orl/emit-run1.py (reported beside it, same requirement)
# and runs one fixed input list through all of them and through (double)(float)v, comparing bit patterns. The same list
# goes through the Python definition py_narrow (copied from orl/emit.py; emit.py is not imported).
# Required: narrow_cur differs from the cast on 0 inputs; narrow_old (and narrow_run1) differ on at least one input and
# every difference is a difference in the sign of zero only; py_narrow equals narrow_cur bit for bit on every input.
#   python -B narrow_regress.py        prints NARROW REGRESSION HELD or FAILED, exit status 0 or 1
# Not covered: values whose conversion overflows (|v| >= 2^128 - 2^103), infinities and NaN are outside the list.
import math, os, random, struct, subprocess, sys
HERE = os.path.dirname(os.path.abspath(__file__))
SRC, EXE = os.path.join(HERE, 'narrow_regress.c'), os.path.join(HERE, 'narrow_regress.exe')
CFLAGS = ['-O2', '-ffp-contract=off', '-fno-math-errno', '-D_CRT_SECURE_NO_WARNINGS']

# ---- copied from orl/emit.py
KK, MM, TT, HH = 536870913.0, 1.5 * 2.0 ** -97, 2.0 ** -126, 2.0 ** -150
def py_narrow(v):
    if abs(v) <= HH: return v * 0.0
    if abs(v) < TT: return (v + MM) - MM
    c = KK * v
    return c - (c - v)
def bits(d): return struct.unpack('<Q', struct.pack('<d', d))[0]
# ----
def frombits(u): return struct.unpack('<d', struct.pack('<Q', u))[0]
def py_cast(v): return struct.unpack('<f', struct.pack('<f', v))[0]     # IEEE round to nearest even, by the C library

C_SRC = r'''// Written by narrow_regress.py. Three variants of narrow against the IEEE conversion (double)(float)v.
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
static const double KK = 536870913.0, MM = 0x1.8p-97, TT = 0x1p-126, HH = 0x1p-150;
// current, copied from orl/gen/sweep.c
static double narrow_cur(double v) { if (fabs(v) <= HH) return v * 0.0; if (fabs(v) < TT) return (v + MM) - MM; double c = KK * v; return c - (c - v); }
// the current one without its first branch
static double narrow_old(double v) { if (fabs(v) < TT) return (v + MM) - MM; double c = KK * v; return c - (c - v); }
// the failed run's, copied from orl/emit-run1.py
static double narrow_run1(double v) { if (fabs(v) < TT && v != 0.0) return (v + MM) - MM; double c = KK * v; return c - (c - v); }
static uint64_t bits(double d) { uint64_t u; memcpy(&u, &d, 8); return u; }
static double frombits(uint64_t u) { double d; memcpy(&d, &u, 8); return d; }
int main(void) { char line[64]; unsigned long long a;
  while (fgets(line, sizeof line, stdin)) { if (sscanf(line, "%llx", &a) != 1) continue;
    volatile double v = frombits(a);
    printf("%016llx %016llx %016llx %016llx %016llx\n", a, (unsigned long long)bits(narrow_cur(v)),
           (unsigned long long)bits(narrow_old(v)), (unsigned long long)bits(narrow_run1(v)),
           (unsigned long long)bits((double)(float)v)); }
  return 0; }
'''

def around(v):
    """v and its two binary64 neighbours."""
    return [math.nextafter(v, -math.inf), v, math.nextafter(v, math.inf)]
def both(vs): return [s * v for v in vs for s in (1.0, -1.0)]

def inputs():
    groups = []
    def add(name, vs): groups.append((name, vs))
    U = 2.0 ** -149                                           # the smallest positive binary32
    add('zeros of both signs', [0.0, -0.0])
    add('+-2^-150 and its binary64 neighbours', both(around(2.0 ** -150)))
    add('+-2^-149', both([U]))
    add('+-(1/2)*2^-149 and +-(3/2)*2^-149', both([0.5 * U, 1.5 * U]))
    add('the smallest negative binary32 (-2^-149), its binary64 neighbours, and the tie points on each side of it '
        '(-2^-150, -1.5*2^-149) with theirs', around(-U) + around(-0.5 * U) + around(-1.5 * U))
    add('the smallest binary64 magnitudes (+-2^-1074, +-2^-1022) and +-2^-151, +-2^-160, +-2^-200',
        both([5e-324, 2.0 ** -1022, 2.0 ** -151, 2.0 ** -160, 2.0 ** -200]))
    rng = random.Random(20261114)
    sub = []
    for _ in range(1500):                                     # binary32 subnormals and the ties between them
        k = rng.randrange(0, 1 << 23)
        sub += [k * U] + around((k + 0.5) * U)
    for k in (0, 1, 2, 3, (1 << 23) - 2, (1 << 23) - 1):      # the ends of the subnormal range
        sub += [k * U] + around((k + 0.5) * U)
    add('seeded: 1506 binary32 subnormals k*2^-149 and the tie (k+1/2)*2^-149 after each with its binary64 '
        'neighbours, both signs', both(sub))
    rnd = []
    for _ in range(3000):                                     # any binary64 value from 2^-160 to 2^-120
        e = rng.randrange(-160, -120)
        rnd.append(math.ldexp(1.0 + rng.random(), e))
    add('seeded: 3000 binary64 values with exponents -160..-121, both signs', both(rnd))
    tiny = [frombits(rng.randrange(1, 0x7FF0000000000000 >> 3) % (bits(2.0 ** -150) + 1) or 1) for _ in range(1000)]
    add('seeded: 1000 binary64 values of magnitude at most 2^-150 (they round to zero), both signs', both(tiny))
    near = around(TT) + around(TT * (1 - 2.0 ** -24)) + around(TT * (1 - 2.0 ** -25)) + around(TT * (1 + 2.0 ** -23)) \
        + around(TT * (1 + 2.0 ** -24)) + around(TT - U) + around(TT - 0.5 * U) + around(TT + 0.5 * U) + around(TT + U)
    for _ in range(1500):
        near.append(math.ldexp(1.0 + rng.random(), rng.choice((-127, -126))))
        m = rng.randrange(1 << 23, 1 << 24)                   # ties between binary32 neighbours in [2^-126, 2^-125)
        near += around(math.ldexp(m + 0.5, -149))
    add('around 2^-126: the threshold, its neighbours and ties, and seeded values and ties in [2^-127, 2^-125), '
        'both signs', both(near))
    one = []
    for d in (2.0 ** -24, 2.0 ** -25):
        one += around(1.0 + d) + around(1.0 - d)
    add('ties around 1: 1 +- 2^-24, 1 +- 2^-25 and their binary64 neighbours (and 1 itself), both signs',
        both(one + around(1.0)))
    FMAX = (2.0 - 2.0 ** -23) * 2.0 ** 127; FPRE = (2.0 - 2.0 ** -22) * 2.0 ** 127
    add('the largest binary32 magnitudes: the largest and the one before it, their binary64 neighbours, the tie '
        'between them, and the last binary64 value before the conversion overflows',
        both(around(FMAX) + around(FPRE) + around((FMAX + FPRE) / 2) + [math.nextafter(2.0 ** 128 - 2.0 ** 103, 0.0)]))
    return groups

def zero_sign_only(a, b):
    """True when a and b are the two zeros, in either order."""
    return {a, b} == {0, 0x8000000000000000}

def holds(lines, cur, con):
    """lines hold the narrow tested here and its constants, each exactly once, and no other definition of narrow."""
    return lines.count(cur) == 1 and lines.count(con) == 1 and sum(l.startswith('static double narrow(') for l in lines) == 1

def live_rows():
    """The copies in this file are held to the live sources (added 2026-11-14, on review): without these rows a change
    to the emitter's narrow would leave this test green, since it would go on testing its own copy."""
    O = os.path.dirname(HERE); rd = lambda p: open(p, encoding='utf-8').read().splitlines()
    cs = C_SRC.splitlines()
    cur = [l for l in cs if l.startswith('static double narrow_cur(')][0].replace('narrow_cur(', 'narrow(', 1)
    con = [l for l in cs if l.startswith('static const double KK')][0]
    rows = [('%s holds the narrow tested here and its constants, line for line' % rel, holds(rd(os.path.join(O, rel)), cur, con))
            for rel in ('gen/sweep.c', 'gen/sweep2.c', 'emit.py', 'emit2.py')]
    me = rd(os.path.abspath(__file__)); a = me.index('# ---- copied from orl/emit.py'); py = me[a + 1:a + 7]
    for rel in ('emit.py', 'emit2.py'):
        t = rd(os.path.join(O, rel)); k = t.index(py[0]) if py[0] in t else -1
        rows.append(('%s holds py_narrow as copied here, line for line' % rel, k >= 0 and t[k:k + 6] == py and sum(l.startswith('def py_narrow(') for l in t) == 1))
    old = cur.replace('if (fabs(v) <= HH) return v * 0.0; ', '', 1)        # plant: a source whose narrow lacks the first branch
    sw = rd(os.path.join(O, 'gen/sweep.c'))
    rows.append(('plant: a sweep.c whose narrow lacks the first branch is refused by the rows above',
                 old != cur and not holds([old if l == cur else l for l in sw], cur, con)))
    return rows

def main():
    ok = True
    open(SRC, 'w', newline='\n').write(C_SRC)
    q = subprocess.run(['clang'] + CFLAGS + [SRC, '-o', EXE], capture_output=True, text=True)
    ver = subprocess.run(['clang', '--version'], capture_output=True, text=True).stdout.splitlines()[0]
    print('build: clang %s narrow_regress.c -o narrow_regress.exe -> exit %d  (%s)' % (' '.join(CFLAGS), q.returncode, ver))
    if q.returncode != 0:
        print(q.stdout + q.stderr); print('NARROW REGRESSION FAILED (the test program did not build)'); return 1
    groups = inputs(); flat = []; owner = []
    for gi, (name, vs) in enumerate(groups):
        for v in vs: flat.append(bits(v)); owner.append(gi)
    q = subprocess.run([EXE], input=''.join('%016x\n' % b for b in flat), capture_output=True, text=True)
    rows = [[int(f, 16) for f in l.split()] for l in q.stdout.splitlines() if l.strip()]
    if q.returncode != 0 or len(rows) != len(flat) or any(r[0] != b for r, b in zip(rows, flat)):
        print('NARROW REGRESSION FAILED (the test program returned %d rows for %d inputs, exit %d)' % (len(rows), len(flat), q.returncode)); return 1
    names = ('current narrow', 'old narrow (no first branch)', 'run-1 narrow (emit-run1.py)')
    n = len(flat); G = len(groups)
    diff = [[0] * G for _ in names]; other = [[0] * G for _ in names]; first = [None] * 3
    py_vs_c = py_vs_cast = pycast_vs_c = 0; first_py = None
    for (b, cur, old, run1, cast), gi in zip(rows, owner):
        for vi, r in enumerate((cur, old, run1)):
            if r != cast:
                diff[vi][gi] += 1
                if not zero_sign_only(r, cast): other[vi][gi] += 1
                if first[vi] is None: first[vi] = (b, r, cast)
        v = frombits(b); p = bits(py_narrow(v)); pc = bits(py_cast(v))
        if p != cur:
            py_vs_c += 1
            if first_py is None: first_py = (b, p, cur)
        if p != pc: py_vs_cast += 1
        if pc != cast: pycast_vs_c += 1
    print('inputs: %d in %d groups (%d distinct bit patterns); seed 20261114' % (n, G, len(set(flat))))
    print('%-6s %-6s %-6s %-6s  group    (columns: inputs, then inputs where each variant differs from (double)(float)v: current, old, run-1)' % ('n', 'cur', 'old', 'run1'))
    for gi, (name, vs) in enumerate(groups):
        print('%-6d %-6d %-6d %-6d  %s' % (len(vs), diff[0][gi], diff[1][gi], diff[2][gi], name))
    for vi, nm in enumerate(names):
        d, o = sum(diff[vi]), sum(other[vi])
        print('%-30s differs from the IEEE cast on %d of %d inputs; differences that are not the sign of zero: %d%s' % (
            nm + ':', d, n, o, '' if first[vi] is None else '; first: input %016x gives %016x, cast %016x' % first[vi]))
    print('Python py_narrow: differs from the C current narrow on %d inputs; from Python\'s own float conversion on %d; '
          'Python\'s conversion differs from C\'s on %d%s' % (py_vs_c, py_vs_cast, pycast_vs_c,
          '' if first_py is None else '; first: input %016x gives %016x, C %016x' % first_py))
    req = [
        ('the current narrow differs on 0 inputs', sum(diff[0]) == 0),
        ('the old variant differs on at least one input', sum(diff[1]) >= 1),
        ('every difference of the old variant is in the sign of zero', sum(other[1]) == 0),
        ('the run-1 variant differs on at least one input, each in the sign of zero', sum(diff[2]) >= 1 and sum(other[2]) == 0),
        ('py_narrow equals the C current narrow on every input', py_vs_c == 0),
        ('py_narrow equals Python\'s float conversion, which equals C\'s, on every input', py_vs_cast == 0 and pycast_vs_c == 0),
    ] + live_rows()
    for text, good in req:
        print('  %-4s %s' % ('ok' if good else 'FAIL', text)); ok &= good
    print('NARROW REGRESSION %s: %d inputs; current differs on %d; old differs on %d (not sign of zero: %d); '
          'run-1 differs on %d (not sign of zero: %d); Python differs from C on %d' % (
              'HELD' if ok else 'FAILED', n, sum(diff[0]), sum(diff[1]), sum(other[1]), sum(diff[2]), sum(other[2]), py_vs_c))
    return 0 if ok else 1

if __name__ == '__main__':
    sys.exit(main())
